// [UNITY-SKILL:SPRITEATLAS]
// [TYPE:PREBUILD]
// Generated by SpriteAtlas V2 Skill
// Genera/actualiza los SpriteAtlas antes de cada build (delivery: built-in).

using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.U2D;
using UnityEngine;
using UnityEngine.U2D;

/// <summary>
/// Agrupa sprites chicos que se dibujan juntos en pocas texturas para bajar draw calls.
/// Los fondos grandes (1920x1080) quedan fuera a propósito: no ganan nada en un atlas.
/// No se fuerza formato por plataforma: el atlas usa los formatos de compresión del
/// proyecto (ETC2 + ASTC), así los celulares sin ASTC siguen recibiendo ETC2.
/// </summary>
public class SpriteAtlasPrebuildGenerator : IPreprocessBuildWithReport
{
    private const string AtlasFolder = "Assets/Atlases";

    public int callbackOrder => 0;

    public void OnPreprocessBuild(BuildReport report) => GenerateAll();

    public static void GenerateAll()
    {
        EditorSettings.spritePackerMode = SpritePackerMode.SpriteAtlasV2;

        Generate($"{AtlasFolder}/Gameplay.spriteatlasv2", new[]
        {
            "Assets/Sprites/Obstacles",
            "Assets/Sprites/Items",
            "Assets/Sprites/Bulet",
            "Assets/Sprites/Explosion",
            "Assets/Sprites/Enemigo Pinches animar.png",
            "Assets/Sprites/EnemigoPanimaaar.psd",
            "Assets/Sprites/PartesRobot.psd",
            "Assets/Sprites/puntito.png",
        });

        Generate($"{AtlasFolder}/UI.spriteatlasv2", new[]
        {
            "Assets/Sprites/UI",
        });

        AssetDatabase.SaveAssets();
    }

    // Solo carpetas/sprites del proyecto (nunca de Packages o built-in)
    private static bool IsValidProjectPath(string path) =>
        path.StartsWith("Assets/") && !path.Contains("/Packages/");

    private static void Generate(string atlasPath, IEnumerable<string> sourcePaths)
    {
        Object[] packables = sourcePaths
            .Where(IsValidProjectPath)
            .Select(p => AssetDatabase.LoadMainAssetAtPath(p))
            .Where(o => o != null)
            .ToArray();

        if (packables.Length == 0)
        {
            Debug.LogWarning($"[SpriteAtlas] Nada para empaquetar en {atlasPath}");
            return;
        }

        SpriteAtlasAsset atlasAsset;
        if (System.IO.File.Exists(atlasPath))
        {
            atlasAsset = SpriteAtlasAsset.Load(atlasPath);
            var runtimeAtlas = AssetDatabase.LoadAssetAtPath<SpriteAtlas>(atlasPath);
            if (runtimeAtlas != null) atlasAsset.Remove(runtimeAtlas.GetPackables());
        }
        else
        {
            atlasAsset = new SpriteAtlasAsset();
            System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(atlasPath));
        }

        atlasAsset.Add(packables);
        SpriteAtlasAsset.Save(atlasAsset, atlasPath);
        AssetDatabase.ImportAsset(atlasPath);
        Configure(atlasPath);
    }

    private static void Configure(string atlasPath)
    {
        if (AssetImporter.GetAtPath(atlasPath) is not SpriteAtlasImporter importer) return;

        var texture = importer.textureSettings;
        texture.filterMode = FilterMode.Bilinear;
        texture.generateMipMaps = false;
        texture.sRGB = true;
        importer.textureSettings = texture;

        // Sin rotación ni tight packing: más seguro para sprites animados y UI
        var packing = importer.packingSettings;
        packing.padding = 4;
        packing.enableRotation = false;
        packing.enableTightPacking = false;
        packing.enableAlphaDilation = true;
        importer.packingSettings = packing;

        var platform = importer.GetPlatformSettings("DefaultTexturePlatform");
        platform.maxTextureSize = 2048;
        platform.textureCompression = TextureImporterCompression.Compressed;
        importer.SetPlatformSettings(platform);

        importer.includeInBuild = true;
        importer.SaveAndReimport();
    }
}
